CREATE TABLE user_session (id BIGINT NOT NULL AUTO_INCREMENT,user_id BIGINT NOT NULL,token_hash BINARY(32) NOT NULL,expires_at DATETIME(6) NOT NULL,last_seen_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),revoked_at DATETIME(6) NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(id),CONSTRAINT uk_user_session_token_hash UNIQUE(token_hash),KEY idx_user_session_user_expiry(user_id,expires_at DESC),CONSTRAINT ck_user_session_expiry CHECK(expires_at>created_at),CONSTRAINT fk_user_session_user FOREIGN KEY(user_id) REFERENCES user_account(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
